import fs from 'fs/promises';
import path from 'path';
import { unstable_cache } from 'next/cache';

const DB_PATH = path.join(process.cwd(), 'posts.json');

interface Post {
  id: string;
  title: string;
  createdAt: string;
}

async function ensureDb() {
  try {
    await fs.access(DB_PATH);
  } catch {
    await fs.writeFile(DB_PATH, JSON.stringify([]));
  }
}

async function readDb(): Promise<Post[]> {
  await ensureDb();
  const data = await fs.readFile(DB_PATH, 'utf-8');
  try {
    return JSON.parse(data);
  } catch {
    return [];
  }
}

// Cached version of getPosts
export const getPosts = unstable_cache(
  async () => {
    return await readDb();
  },
  ['posts-data'], // Key parts for the cache key
  { tags: ['posts'] } // Tags for invalidation
);

export async function addPost(title: string) {
  await ensureDb();
  const posts = await readDb();
  const newPost: Post = {
    id: Date.now().toString(),
    title,
    createdAt: new Date().toISOString(),
  };
  posts.push(newPost);
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
  return newPost;
}

