args.content:
import { getPosts } from '@/lib/posts';
import { createPost } from '@/app/actions';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '20px' }}>
      <h1>Posts</h1>

      <div style={{ marginBottom: '20px' }}>
        <p>Create a new post to test cache invalidation.</p>
        <form action={createPost}>
          <input 
            name="title" 
            type="text" 
            placeholder="New post title" 
            required 
            style={{ 
              border: '1px solid #ccc', 
              padding: '8px',
              borderRadius: '4px',
              marginRight: '10px'
            }} 
          />
          <button 
            type="submit" 
            style={{ 
              padding: '8px 16px',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Create Post
          </button>
        </form>
      </div>

      <div style={{ border: '1px solid #eee', borderRadius: '8px', padding: '16px' }}>
        <h2>Current Posts (Cached)</h2>
        {posts.length === 0 ? (
          <p>No posts yet.</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {posts.map((post) => (
              <li key={post.id} style={{ padding: '8px 0', borderBottom: '1px solid #eee' }}>
                <strong>{post.title}</strong>
                <br />
                <small style={{ color: '#666' }}>
                  ID: {post.id} • Created: {new Date(post.createdAt).toLocaleString()}
                </small>
              </li>
            ))}
          </ul>
        )}
      </div>
    </main>
  );
}

