import { updateTag } from 'next/cache';
import { addPost } from '@/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;

  if (!title) {
    return;
  }

  await addPost(title);

  // Use updateTag for read-your-own-writes semantics in Server Actions
  // This invalidates the 'posts' cache tag and ensures fresh data on the next render
  updateTag('posts');
}

